# Install the standalone Thread border router as owner user units (see ../../thread-border-router.md).
# Feed to /bin/sh on stdin as root. Prerequisites: radio on the hub image (CPC protocol v5); hub off (iot_mode 0).
# Does not join a network: run otbr-join.sh once afterwards (doc step 3). Quiet Home's Info page can then switch it.
set -eu
H=/opt/usr/home/owner; UD=$H/.config/systemd/user; Q=/opt/usr/share/quiet-otbr
HUB=/opt/usr/apps/com.samsung.tizen.smartthings-hub/bin; T=/opt/var/lib/thread
B=/opt/usr/share/quiet-tizen-backups/thread-border-router
usr(){ env HOME=$H XDG_RUNTIME_DIR=/run/user/5001 DBUS_SESSION_BUS_ADDRESS=kernel:path=/sys/fs/kdbus/5001-user/bus systemctl --user "$@"; }
[ "$(id -u)" = 0 ]
for n in quiet-otbr-cpcd.service quiet-otbr-agent.service quiet-otbr-forward.service quiet-otbr-switch.path; do [ ! -e "$UD/default.target.wants/$n" ] || { echo "$n already enabled - refusing (run otbr-restore.sh first)"; exit 3; }; done
[ "$(buxton2ctl get system db/iot/thing/iot_mode | cut -d" " -f5)" = 0 ] || { echo "SmartThings hub is enabled - refusing"; exit 3; }
# 1. first-run backup of everything this changes (never overwritten)
if [ ! -d "$B" ]; then
  mkdir -p "$B"; chmod 700 "$B"
  [ -d "$T" ] && cp -a "$T" "$B/thread"
  { echo "thread_dir_label=$(chsmack "$T" 2>/dev/null | sed 's/.*access="//; s/".*//')"; for f in "$T"/*.data; do [ -f "$f" ] && echo "file=$f $(stat -c %U:%G:%a "$f") $(chsmack "$f" | sed 's/.*access="//; s/".*//')"; done; getcap "$HUB/otbr-agent"; } > "$B/before.txt" 2>&1 || true
  for k in net.ipv4.ip_forward net.ipv6.conf.all.forwarding net.ipv6.conf.eth0.forwarding net.ipv6.conf.wlan0.forwarding net.ipv6.conf.eth0.accept_ra net.ipv6.conf.wlan0.accept_ra; do sysctl "$k" >> "$B/sysctl-before.txt" 2>/dev/null || true; done
  iptables-save > "$B/iptables-before.txt"; ip6tables-save > "$B/ip6tables-before.txt"
  echo "backup: $B"
fi
# 2. exact private copy of Samsung's agent with its three capabilities effective (vendor file untouched)
mkdir -p "$Q"; chown root:root "$Q"; chmod 755 "$Q"; chsmack -a User "$Q"
cp -a "$HUB/otbr-agent" "$Q/otbr-agent.new"
[ "$(sha256sum < "$HUB/otbr-agent")" = "$(sha256sum < "$Q/otbr-agent.new")" ]
chown root:users "$Q/otbr-agent.new"; chmod 750 "$Q/otbr-agent.new"
setcap cap_dac_override,cap_net_admin,cap_net_raw=ep "$Q/otbr-agent.new"; mv "$Q/otbr-agent.new" "$Q/otbr-agent"
chsmack "$Q/otbr-agent" | grep -q "User::Pkg::com.samsung.tizen.smartthings-hub::RO" || { echo "agent copy lost its package label - refusing"; exit 4; }
# 3. let the owner read and write the saved network (modes stay 0600)
[ -d "$T" ] || { mkdir -p "$T"; chown owner:users "$T"; chmod 755 "$T"; }
chsmack -a User "$T"; for f in "$T"/*.data; do [ -f "$f" ] && chown owner:users "$f"; done
# 4. factory-data marker: Samsung's setup runs its radio factory test (killall cpcd) only when /tmp/iot_factory_data is missing
if [ ! -s "$Q/iot_factory_data" ]; then
  if [ -s /tmp/iot_factory_data ]; then cp /tmp/iot_factory_data "$Q/iot_factory_data"; else
    fw=$(tr -d "\n" < $H/share/com.samsung.tv.iot-hub-control/fw_version 2>/dev/null || true)
    e=$("$HUB/ot-ctl" eui64 2>/dev/null | tr -d "\r" | grep -E "^[0-9a-f]{16}$" || true); r=""
    for b in $(echo "$e" | sed "s/../& /g"); do r="$b${r:+:}$r"; done  # radio EUI-64, reversed like Samsung writes it
    printf '{"iot_hub_eui":"%s","iot_hub_fw":"%s"}' "$r" "$fw" > "$Q/iot_factory_data"
  fi
  chown root:users "$Q/iot_factory_data"; chmod 644 "$Q/iot_factory_data"; chsmack -a User "$Q/iot_factory_data"
fi
# 4b. standby: block iot-hub-control, install the USB power keeper (keeps the radio powered in standby)
# Samsung's iot-hub-control (started on demand through its IHubControl RPC port) switches the radio module off when the
# TV enters standby while the SmartThings hub is off. Blocked in the app registry (same lever as the privacy batches);
# the inverse re-enables it.
DB=/opt/dbspace/.pkgmgr_parser.db
if [ "$(sqlite3 -readonly $DB "select app_disable from package_app_info where app_id='com.samsung.tv.iot-hub-control'")" = false ]; then
  mkdir -p "$B"; [ -e "$B/registry-before-ihc.db" ] || cp -a $DB "$B/registry-before-ihc.db"
  sqlite3 -bail $DB "BEGIN IMMEDIATE; UPDATE package_app_info SET app_disable='true' WHERE app_id='com.samsung.tv.iot-hub-control' AND app_disable='false'; COMMIT;"
  [ "$(sqlite3 -readonly $DB 'PRAGMA quick_check;')" = ok ]
  touch "$B/ihc-disabled-by-quiet-otbr"
  /usr/bin/dotnet /opt/usr/share/quiet-tizen-backups/privacy-phaseB-20261024T135601/AppMetadata.dll reload-owner >/dev/null 2>&1 || true
  P=$(pgrep -f /bin/iot-hub-control | head -n1); [ -n "$P" ] && kill $P || true
fi
base64 -d > "$Q/quiet-otbr-usbpower.dll.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$Q/quiet-otbr-usbpower.dll.new" | cut -d" " -f1)" = afd98e2b38b78f9f868e36f280b2fbad441b6a827936edecbec743618b92836e ]
chown root:users "$Q/quiet-otbr-usbpower.dll.new"; chmod 644 "$Q/quiet-otbr-usbpower.dll.new"; chsmack -a User "$Q/quiet-otbr-usbpower.dll.new"; mv "$Q/quiet-otbr-usbpower.dll.new" "$Q/quiet-otbr-usbpower.dll"
base64 -d > "$Q/quiet-otbr-usbpower.runtimeconfig.json.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$Q/quiet-otbr-usbpower.runtimeconfig.json.new" | cut -d" " -f1)" = a0882085ebc8618322fb819cc0e92bac0499419af91124d05f6d27662818ea83 ]
chown root:users "$Q/quiet-otbr-usbpower.runtimeconfig.json.new"; chmod 644 "$Q/quiet-otbr-usbpower.runtimeconfig.json.new"; chsmack -a User "$Q/quiet-otbr-usbpower.runtimeconfig.json.new"; mv "$Q/quiet-otbr-usbpower.runtimeconfig.json.new" "$Q/quiet-otbr-usbpower.runtimeconfig.json"
# 5. units
LBL=$(chsmack $H | sed 's/.*access="//; s/".*//')
[ -d "$UD/default.target.wants" ] || { mkdir -p "$UD/default.target.wants"; chown owner:users $H/.config $H/.config/systemd "$UD" "$UD/default.target.wants"; chsmack -a "$LBL" $H/.config $H/.config/systemd "$UD" "$UD/default.target.wants"; }
base64 -d > "$UD/quiet-otbr-usbpower.service.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$UD/quiet-otbr-usbpower.service.new" | cut -d" " -f1)" = 3445f996edca9f28631c2958d110661700888a3749c77e53f2199b9504b3184f ]
chown owner:users "$UD/quiet-otbr-usbpower.service.new"; chmod 644 "$UD/quiet-otbr-usbpower.service.new"; chsmack -a "$LBL" "$UD/quiet-otbr-usbpower.service.new"; mv "$UD/quiet-otbr-usbpower.service.new" "$UD/quiet-otbr-usbpower.service"
ln -sf ../quiet-otbr-usbpower.service "$UD/default.target.wants/quiet-otbr-usbpower.service"; chown -h owner:users "$UD/default.target.wants/quiet-otbr-usbpower.service"
base64 -d > "$UD/quiet-otbr-cpcd.service.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$UD/quiet-otbr-cpcd.service.new" | cut -d" " -f1)" = f9b4e04587cc1b6dff6ca89229b8ae20533107e8498be71df227ca0b9db74994 ]
chown owner:users "$UD/quiet-otbr-cpcd.service.new"; chmod 644 "$UD/quiet-otbr-cpcd.service.new"; chsmack -a "$LBL" "$UD/quiet-otbr-cpcd.service.new"; mv "$UD/quiet-otbr-cpcd.service.new" "$UD/quiet-otbr-cpcd.service"
ln -sf ../quiet-otbr-cpcd.service "$UD/default.target.wants/quiet-otbr-cpcd.service"; chown -h owner:users "$UD/default.target.wants/quiet-otbr-cpcd.service"
base64 -d > "$UD/quiet-otbr-agent.service.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$UD/quiet-otbr-agent.service.new" | cut -d" " -f1)" = 888444dd74b23e64db182ce71746a7ea09ebf9d40a226d62dc9d9589d360e2d7 ]
chown owner:users "$UD/quiet-otbr-agent.service.new"; chmod 644 "$UD/quiet-otbr-agent.service.new"; chsmack -a "$LBL" "$UD/quiet-otbr-agent.service.new"; mv "$UD/quiet-otbr-agent.service.new" "$UD/quiet-otbr-agent.service"
ln -sf ../quiet-otbr-agent.service "$UD/default.target.wants/quiet-otbr-agent.service"; chown -h owner:users "$UD/default.target.wants/quiet-otbr-agent.service"
base64 -d > "$UD/quiet-otbr-forward.service.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$UD/quiet-otbr-forward.service.new" | cut -d" " -f1)" = 0394de661d3a4ee2dde8c818e5485bb15f8b6b04ecef678a0aa922dfe6852f7b ]
chown owner:users "$UD/quiet-otbr-forward.service.new"; chmod 644 "$UD/quiet-otbr-forward.service.new"; chsmack -a "$LBL" "$UD/quiet-otbr-forward.service.new"; mv "$UD/quiet-otbr-forward.service.new" "$UD/quiet-otbr-forward.service"
ln -sf ../quiet-otbr-forward.service "$UD/default.target.wants/quiet-otbr-forward.service"; chown -h owner:users "$UD/default.target.wants/quiet-otbr-forward.service"
base64 -d > "$UD/quiet-otbr-switch.service.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$UD/quiet-otbr-switch.service.new" | cut -d" " -f1)" = ed643c450b6bbb15f5f4727e57957d871312cb190d54fffe2082d0174c131953 ]
chown owner:users "$UD/quiet-otbr-switch.service.new"; chmod 644 "$UD/quiet-otbr-switch.service.new"; chsmack -a "$LBL" "$UD/quiet-otbr-switch.service.new"; mv "$UD/quiet-otbr-switch.service.new" "$UD/quiet-otbr-switch.service"
base64 -d > "$UD/quiet-otbr-switch.path.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$UD/quiet-otbr-switch.path.new" | cut -d" " -f1)" = dc7897ad025a0f5f6aade7120bf45dcd3dc02ae86bf093b71b8a9433af93f579 ]
chown owner:users "$UD/quiet-otbr-switch.path.new"; chmod 644 "$UD/quiet-otbr-switch.path.new"; chsmack -a "$LBL" "$UD/quiet-otbr-switch.path.new"; mv "$UD/quiet-otbr-switch.path.new" "$UD/quiet-otbr-switch.path"
ln -sf ../quiet-otbr-switch.path "$UD/default.target.wants/quiet-otbr-switch.path"; chown -h owner:users "$UD/default.target.wants/quiet-otbr-switch.path"
usr daemon-reload
usr start --no-block quiet-otbr-switch.path quiet-otbr-usbpower.service quiet-otbr-cpcd.service quiet-otbr-agent.service quiet-otbr-forward.service
for n in quiet-otbr-usbpower.service quiet-otbr-cpcd.service quiet-otbr-agent.service quiet-otbr-forward.service quiet-otbr-switch.path; do echo "$n: $(usr is-enabled $n)"; done
echo "INSTALLED - log: /run/user/5001/quiet-otbr.log"
